    for f in ("/proc/net/tcp","/proc/net/tcp6"):
        try:
            lines = open(f).read().splitlines()[1:]
        except FileNotFoundError:
            continue
        for ln in lines:
            p = ln.split()
            if p[3] == "0A":  # LISTEN
                res.add(int(p[1].split(":")[1], 16))
    return sorted(res)
